package com.mr486.msplatform.serviceb.dbchangelogs;
import io.mongock.api.annotations.ChangeUnit;import io.mongock.api.annotations.Execution;import io.mongock.api.annotations.RollbackExecution;import org.bson.Document;import org.springframework.data.mongodb.core.MongoTemplate;import java.util.List;
@ChangeUnit(id="seed-service-b", order="001", author="mr486")
public class DataBaseChangeLog{ private final MongoTemplate mongoTemplate; public DataBaseChangeLog(MongoTemplate mongoTemplate){this.mongoTemplate=mongoTemplate;} @Execution public void seed(){ if(mongoTemplate.getCollection("resources_b").countDocuments()>0)return; mongoTemplate.getCollection("resources_b").insertMany(List.of(new Document("name","ResourceB 1").append("description","Premiere ressource MongoDB"),new Document("name","ResourceB 2").append("description","Deuxieme ressource MongoDB"))); } @RollbackExecution public void rollback(){ mongoTemplate.getCollection("resources_b").deleteMany(new Document()); }}
